const ip = $input.item.json.body.payload.source_ip || '192.168.1.100';
// Giả lập AbuseIPDB cho Port Scan
// Nếu IP là 103.11.22.33 -> Score = 90 (> 80)
// Nếu IP khác -> Score = 20 (< 80)
let score = (ip === '103.11.22.33') ? 90 : 20;

return {
  data: {
    ipAddress: ip,
    abuseConfidenceScore: score
  }
};

